#!/usr/bin/env python3
"""Read-only candidate/immutable-Git text, provider and full addition-tree proof."""
from pathlib import Path
import argparse,base64,hashlib,json,re,subprocess
ap=argparse.ArgumentParser();ap.add_argument('--commit');ap.add_argument('--repo',default='.');ap.add_argument('--candidate-root');ap.add_argument('--report');a=ap.parse_args()
repo=Path(a.repo).resolve(); here=Path(__file__).resolve().parent
report_path='reports/cc16_native_gui_icon_cropped_quad_storage.json'
def git(*args):return subprocess.check_output(['git','-C',str(repo),*args])
if a.commit:
 commit=git('rev-parse',a.commit).decode().strip();raw=git('show',commit+':'+report_path);parent=git('rev-parse',commit+'^').decode().strip()
 def get(path):return git('show',commit+':'+path)
else:
 root=Path(a.candidate_root) if a.candidate_root else here/'candidate'
 raw=Path(a.report).read_bytes() if a.report else (root/report_path).read_bytes()
 def get(path):return (root/path).read_bytes()
 commit=None
r=json.loads(raw);checks=0
def ck(value,message):
 global checks
 if not value:raise AssertionError(message)
 checks+=1
def sha(data):return hashlib.sha256(data).hexdigest()
if not a.commit:parent=r['historical_candidate_base']
paths=r['owned_paths'];ck(len(paths)==4 and len(set(paths))==4,'four unique additions')
if a.commit:
 changed=git('diff-tree','--no-commit-id','--name-status','-r',commit).decode().splitlines()
 ck(set(changed)=={'A\t'+p for p in paths},'actual immutable commit exactly four additions')
for path,p in r['known_postimages'].items():
 b=get(path);ck(len(b)==p['bytes'] and sha(b)==p['sha256'],'postimage '+path)
 ck(b==base64.b64decode(p['base64']),'full known postimage '+path)
for p in r['unchanged_input_pins']:
 b=git('show',parent+':'+p['path']);ck(len(b)==p['bytes'] and sha(b)==p['sha256'],'actual parent provider '+p['path'])
 if commit:ck(get(p['path'])==b,'unchanged current provider '+p['path'])
h=get(paths[0]).decode();c=get(paths[1]).decode()
ck('std::uint32_t native_spill_words[6];' in h and '== 24' in h,'six ordinary retained spill words')
ck('(&actual_argument_homes)[7]' in h,'seven mutable actual argument homes')
ck('homes1/2/3/6' in h,'exact home overwrite inventory')
ck('noexcept' not in h and 'noexcept' not in c,'no new noexcept')
ck(c.count('__asm {')==1,'single asm region')
ck(not re.search(r'\b(?:call|push|pop|ret)\b',c,re.I),'no helper/callee/private-ABI assembly calls')
ck(not re.search(r'\b(?:throw|catch|try|new|delete|memcpy|memmove|std::function)\b',c),'no new Source helper/policy')
for s in ['auto* const source_homes = &actual_argument_homes[0];','auto* const source_spills = &frame.native_spill_words[0];','source_one = &actual_one_00d7a24c;','source_vertical = &actual_vertical_scale_00e12fd0;']:
 ck(s in c,'address-only entry metadata '+s)
ck('std::uint32_t source_saved_ecx;' in c and 'std::uint32_t source_switch_targets[5];' in c,'ordinary no-DMI Source carriers')
chunks={m.group(1):[x.strip() for x in m.group(2).splitlines() if x.strip()] for m in re.finditer(r'^    quad_([0-9a-f]{8}):\n(.*?)(?=^    quad_|\Z)',c,re.M|re.S)}
ck(len(chunks)==472,'all Native instruction labels')
scaffold={'SUB ESP,0x18','ADD ESP,0x18','PUSH ESI','POP ESI','RET 0x1c'}
intervals=[(0xab1944,0xab19b0),(0xab1a46,0xab1b2d),(0xab1b6f,0xab1c8f),(0xab1c96,0xab1da1),(0xab1dc5,0xab1ec2)]
fp_ops=[];native_rows=[];writes=set()
for row in r['static_proof']['rows']:
 s=row['native'];addr=row['address'];number=int(addr,16);native_rows.append(addr+': '+s+'\n');expected=[]
 delta=4 if any(lo<=number<=hi for lo,hi in intervals) else 0
 for cell in row['cells']:
  ck(cell['additional_saved_esi_bytes']==delta,'manual saved-ESI interval '+addr)
  ck(cell['canonical_B_offset']==cell['native_esp_offset']-delta,'canonical cell '+addr)
  canonical=cell['canonical_B_offset'];bank='spills' if canonical<0x18 else 'homes';offset=canonical if bank=='spills' else canonical-0x1c
  ck(cell['bank']==bank and cell['index']==offset//4 and offset%4==0,'live backing cell '+addr)
  if bank=='spills':
   is_write=bool(re.match(r'(?:MOVSS|FSTP|MOV) (?:float|dword) ptr \[ESP',s))
   ck(is_write or cell['index'] in writes,'private spill first store precedes read '+addr)
   if is_write:writes.add(cell['index'])
 if s in scaffold:expected=['jmp quad_source_return'] if s.startswith('RET') else []
 elif s=='JMP dword ptr [EAX*0x4 + 0xab1ed4]':expected=['jmp dword ptr source_switch_targets[eax*4]']
 else:
  t=s
  def subcell(m):
   native=int(m.group(1) or '0',16);canonical=native-delta
   ck(canonical in list(range(0,0x18,4))+list(range(0x1c,0x38,4)),'actual mapped cell range '+addr)
   return '[{} + {}]'.format('ebx' if canonical<0x18 else 'edi',canonical if canonical<0x18 else canonical-0x1c)
  t=re.sub(r'\[ESP(?: \+ (0x[0-9a-f]+))?\]',subcell,t)
  if t.startswith('J'):t=re.sub(r'0x00(ab[0-9a-f]{4})',lambda m:'quad_00'+m.group(1),t)
  t=re.sub(r'\bST([0-7])\b',lambda m:'st('+m.group(1)+')',t).replace('float ptr','dword ptr')
  op=t.split()[0]
  if op in ('FMULP','FADDP','FSUBP','FSUBRP'):
   if ' ' not in t:t+=' st(1), st(0)'
   elif ',' not in t:t+=', st(0)'
  if op=='FXCH' and ' ' not in t:t+=' st(1)'
  if op in ('FMUL','FADD','FSUB','FSUBR') and re.fullmatch(r'[A-Z]+ st\([0-7]\)',t):t=op+' st(0), '+t.split()[1]
  constant=None
  for literal,name in [('[0x00d7a24c]','source_one'),('[0x00e12fd0]','source_vertical')]:
   if literal in t:constant=name;t=t.replace(literal,'[ecx]')
  expected=['mov source_saved_ecx, ecx','mov ecx, '+constant,t.lower(),'mov ecx, source_saved_ecx'] if constant else [t.lower()]
 ck(row['source']==expected and chunks[addr]==expected,'exact complete Native row adaptation '+addr)
 if s.split()[0].startswith('F'):fp_ops.append(s)
ck(len(writes)==6 and len(fp_ops)==199,'six prefix spill writes/all199 x87')
ck(sha(''.join(native_rows).encode())==r['Native']['assembly_sha256'],'full Native listing reconstruction')
ck(sha(base64.b64decode(r['Native']['body_base64']))==r['Native']['sha256'],'frozen installed full body')
for i,target in enumerate(r['Native']['switch_targets']):
 ck('lea eax, quad_'+target+'\n        mov source_switch_targets['+str(i*4)+'], eax' in c,'Source switch label identity '+target)
ck('cmp eax,0x4' in c and 'ja quad_00ab1ec7' in c,'all full mode bits/default branch')
# Whole recursive tree: candidate additions are removed to reproduce the exact
# ACTUAL parent tree. Historical baseline equality is reported, never assumed.
def base_entries():
 out={}
 for x in git('ls-tree','-rz','--full-tree',parent).split(b'\0'):
  if not x:continue
  meta,p=x.split(b'\t',1);mode,typ,oid=meta.split(b' ')
  if typ==b'blob':out[p.decode()]=(mode.decode(),oid.decode())
 return out
def blob(data):return hashlib.sha1(b'blob '+str(len(data)).encode()+b'\0'+data).hexdigest()
def tree(entries):
 direct={};groups={}
 for name,value in entries.items():
  if '/' in name:first,rest=name.split('/',1);groups.setdefault(first,{})[rest]=value
  else:direct[name]=value
 for name,items in groups.items():direct[name]=('40000',tree(items))
 ordered=sorted(direct,key=lambda x:x+('/' if direct[x][0]=='40000' else ''))
 b=b''.join(direct[x][0].encode()+b' '+x.encode()+b'\0'+bytes.fromhex(direct[x][1]) for x in ordered)
 return hashlib.sha1(b'tree '+str(len(b)).encode()+b'\0'+b).hexdigest()
entries=base_entries();parent_tree=git('rev-parse',parent+'^{tree}').decode().strip();ck(tree(entries)==parent_tree,'complete parent recursive tree')
for path in paths:ck(path not in entries,'actual baseline addition absent '+path)
post=dict(entries);forward_states=[{'added_paths':0,'tree':parent_tree}]
for path in paths:
 post[path]=('100644',blob(get(path)));forward_states.append({'added_path':path,'tree':tree(post)})
post_tree=tree(post)
if commit:ck(post_tree==git('rev-parse',commit+'^{tree}').decode().strip(),'full actual four-addition tree forward')
reverse_states=[{'remaining_paths':4,'tree':post_tree}]
for path in reversed(paths):
 del post[path];reverse_states.append({'removed_path':path,'tree':tree(post)})
ck(tree(post)==parent_tree,'full four-path recursive inverse')
print(json.dumps({'checks':checks,'verdict':'qualified_static_text_tree_PASS_uncompiled','commit':commit,'actual_parent':parent,'historical_candidate_base':r['historical_candidate_base'],'parent_equals_historical':parent==r['historical_candidate_base'],'actual_parent_tree':parent_tree,'candidate_or_commit_tree':post_tree,'forward_states':forward_states,'reverse_states':reverse_states,'native_rows':472,'x87_rows':199,'Source_runtime_activation_credit':False},indent=2))
